import { LogOut, Search } from "lucide-react";
import { useState } from "react";
import { globalSearch } from "@/services/search";
import { ThemeToggle } from "../ui/theme-toggle";

export default function Header() {
    // ... logic remains same ...
    const logout = async () => {
        await fetch("/api/auth/logout", {
            method: "POST",
            credentials: "include",
        });

        window.location.href = "/login";
    };

    const [query, setQuery] = useState("");
    const [results, setResults] = useState<any[]>([]);

    const search = async (q: string) => {
        setQuery(q);

        if (!q) return setResults([]);

        const data = await globalSearch(q);
        setResults(data);
    };

    return (
        <header className="h-20 bg-surface-lowest/60 backdrop-blur-md sticky top-0 z-40 flex items-center justify-between px-8">
            <h2 className="text-xl font-bold tracking-tight text-foreground">
                Dashboard
            </h2>

            <div className="flex items-center gap-6">
                <div className="relative">
                    <input
                        value={query}
                        onChange={(e) => search(e.target.value)}
                        placeholder="Type to search..."
                        className="bg-surface-lowest border border-border/10 rounded-sm px-5 py-2 w-80 text-sm focus:outline-none focus:border-primary/50 transition-all placeholder:text-muted-foreground/50"
                    />
                    {results.length > 0 && (
                        <div className="absolute top-full left-0 bg-surface-highest/90 backdrop-blur-xl border border-border/10 rounded-sm mt-3 w-full shadow-2xl z-50 py-3 overflow-hidden animate-in fade-in slide-in-from-top-2">
                            {results.map((r: any, i: number) => (
                                <div key={i} className="px-5 py-2.5 hover:bg-primary/10 cursor-pointer transition-colors group">
                                    <p className="text-sm font-semibold text-foreground group-hover:text-primary transition-colors">{r.name || r.id}</p>
                                    <p className="text-xs text-muted-foreground">{r.sku || r.status}</p>
                                </div>
                            ))}
                        </div>
                    )}
                </div>

                <div className="flex items-center gap-3 border-l border-border/10 pl-6">
                  <ThemeToggle />
                  <button
                      onClick={logout}
                      className="p-2 text-muted-foreground hover:text-destructive transition-colors"
                      title="Logout"
                  >
                      <LogOut size={20} />
                  </button>
                </div>
            </div>
        </header>
    );
}