"use client";

import { ReactNode } from "react";
import { motion } from "framer-motion";

interface MetricCardProps {
  title: string;
  value: string | number;
  icon: ReactNode;
  description?: string;
  trend?: {
    value: number;
    isPositive: boolean;
  };
}

export default function MetricCard({
  title,
  value,
  icon,
  description,
  trend
}: MetricCardProps) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      whileHover={{ y: -2 }}
      className="bg-surface-low p-8 rounded-sm flex flex-col justify-between transition-all hover:bg-surface-high h-full group cursor-default"
    >
      <div className="flex items-start justify-between">
        <div className="space-y-1">
          <p className="text-[10px] font-bold text-muted-foreground uppercase tracking-[0.1em]">
            {title}
          </p>
          <h3 className="text-4xl font-black text-foreground tracking-tighter transition-transform group-hover:scale-[1.02] origin-left">
            {value}
          </h3>
        </div>
        <div className="p-3 bg-surface-lowest text-primary rounded-sm transition-colors group-hover:bg-primary group-hover:text-primary-foreground">
          {icon}
        </div>
      </div>

      <div className="mt-8 flex items-center justify-between border-t border-border/5 pt-4">
        {description && (
          <p className="text-[11px] font-medium text-muted-foreground/60 italic">
            {description}
          </p>
        )}
        {trend && (
          <div className={`flex items-center gap-1.5 text-[11px] font-bold px-2 py-0.5 rounded-full ${
            trend.isPositive ? "text-emerald-400" : "text-rose-400"
          }`}>
            <span className="opacity-70">{trend.isPositive ? "▲" : "▼"}</span>
            <span>{Math.abs(trend.value)}%</span>
          </div>
        )}
      </div>
    </motion.div>
  );
}
